import json, yaml, glob, subprocess, shutil, os
H='workplan/pipeline-state-graph/'
g=json.load(open(H+'graph.json'))
c=yaml.safe_load(open(H+'conflicts.yaml')); m=yaml.safe_load(open(H+'machines.yaml')); k=yaml.safe_load(open(H+'capabilities.yaml'))
cited=set()
for x in c['conflicts']: cited|=set(x['atoms'])|{i for s in x['sides'] for i in s['atoms']}
for sc in c.get('status_corrections',[]): cited|={sc['atom'],*sc['by']}
for mm in m['machines']: cited|=set(mm.get('atoms',[]))
for cap in k['capabilities'].values():
    for p in cap['predicates']: cited|=set(p.get('atoms',[]))
pr=g['probes']; 
for v in (pr.values() if isinstance(pr,dict) else pr): cited|=set(v['atoms'])
files=glob.glob(H+'atoms/atoms-*.jsonl')
unc=cit=None
for f in files:
    for l in open(f,encoding='utf-8'):
        if not l.strip(): continue
        d=json.loads(l)
        if d['id'] not in cited and unc is None and not d['source'].endswith(('.db',)) and ':' in d['source']: unc=(f,d['id'])
        if d['id'] in cited and cit is None and ':' in d['source']: cit=(f,d['id'])
print('uncited example',unc,'cited example',cit,'cited total',len(cited))
def mutate(f,aid):
    s=open(f,encoding='utf-8').read(); lines=s.split('\n'); out=[]
    for l in lines:
        if l.strip() and json.loads(l)['id']==aid:
            d=json.loads(l); l=l.replace(json.dumps(d['quote'],ensure_ascii=False)[:-1], json.dumps(d['quote'],ensure_ascii=False)[:-1]+' ZZZ-NOT-IN-SOURCE',1)
        out.append(l)
    open(f,'w',encoding='utf-8').write('\n'.join(out)); return s
for label,(f,aid) in (('UNCITED',unc),('CITED',cit)):
    orig=mutate(f,aid)
    r=subprocess.run(['python3',H+'build_graph.py','--check'],capture_output=True,text=True)
    tail=[x for x in r.stdout.splitlines() if 'FAIL' in x or 'failure' in x]
    print(label,aid,'->',tail[:2])
    open(f,'w',encoding='utf-8').write(orig)
