    @classmethod
    def valid_code(cls, v: str) -> str:
        """Validate population code format."""
        valid = {e.value for e in PopulationCode}
        if v not in valid:
            raise ValueError(
                f"Unknown population code: '{v}'. "
                f"Valid codes: {sorted(valid)}"
            )
        return v

