import ast, subprocess, pathlib, collections
tracked = [p for p in subprocess.run(["git","ls-files","*.py"],capture_output=True,text=True).stdout.split("\n") if p and not p.startswith(("transcripts/","sessions/","_archived/","versions/","scripts/migrations/"))]
used = collections.Counter(); strings = collections.Counter()
for p in tracked:
    try: tree = ast.parse(pathlib.Path(p).read_text())
    except Exception: continue
    for n in ast.walk(tree):
        if isinstance(n, ast.Name): used[n.id] += 1
        elif isinstance(n, ast.Attribute): used[n.attr] += 1
        elif isinstance(n, ast.Constant) and isinstance(n.value, str) and len(n.value) < 60: strings[n.value] += 1
        elif isinstance(n, ast.alias): used[n.name] += 1
# also shell/yaml mentions of function names run via -c
others = "\n".join(pathlib.Path(p).read_text(errors="ignore") for p in subprocess.run(["git","ls-files","*.sh","*.yaml","*.yml","*.md"],capture_output=True,text=True).stdout.split("\n") if p and not p.startswith(("transcripts/","sessions/","_archived/","versions/","scripts/migrations/","audits/","workplan/20")))
